‪ ،‬وأحد الورثة يرغب‬\n ‫‪330‬‬     ‫يف شراء عقار منها‪ ،‬وآخر يدعي متلكه يف‬        ‫قسمة تركة‬   ‫‪17‬‬\n          ‫احلقيقة لعقار منها وأن مورث أوصى له به‬\n\n         ‫مطالبة ورثة مبحاسبة أحدهم املتولي تأجير‬\n ‫‪339‬‬      ‫عقاراتهم املورثة وتوضيح دخلها وتسليمهم‬      ‫قسمة تركة‬   ‫‪18‬‬\n                        ‫نصيبهم منها‬\n\n         ‫مطالبة بقسمة تركة‪ ،‬وبعض الورثة يدعي‬\n ‫‪365‬‬              ‫وصية املورث له بعقار‬                ‫قسمة تركة‬   ‫‪19‬‬\n\n          ‫مطالبة بعض الورثة للبقية بإمتام بيع عقار‬\n ‫‪374‬‬        ‫موروث مت بيعه مبوافقة جميع الورثة‬         ‫قسمة تركة‬   ‫‪20‬‬\n\f‫الصفحة‬                    ‫املوضوع‬                        ‫التصنيف‬    ‫م‬\n\n         ‫احلكم ببيع عقار موروث باملزاد العلني وقسمة‬\n          ‫ثمنه بني الورثة بحسب أنصابهم الشرعية بعد‬\n ‫‪390‬‬       ‫مطالبة املدعية بذلك‪ ،‬وتخلف أحد املدعى‬        ‫قسمة تركة‬   ‫‪21‬‬\n                             ‫عليهم‬\n\n          ‫مطالبة ببيع عقار موروث وإعطاء كل وارث‬\n ‫‪398‬‬      ‫نصيبه الشرعي‪ ،‬ويف الورثة قاصر وموصية‬          ‫قسمة تركة‬   ‫‪22‬‬\n                       ‫بثلث مالها‬\n\n           ‫مطالبة وارث ببيع عقارات مورثهم باملزاد‬\n           ‫العلني وتسليمه نصيبه منها‪ ،‬ودم إمكان‬\n ‫‪408‬‬      ‫قسمتها بني الورثة‪ ،‬وصكوكها خالية من‬           ‫قسمة تركة‬   ‫‪23‬‬\n                        ‫املساحة الكلية‬\n\n          ‫مطالبة وارثة بنصيبها مما تدعيه من أمالك‬\n ‫‪420‬‬                 ‫مورثها وال بينة لها‬                ‫قسمة تركة‬   ‫‪24‬‬\n\n           ‫مطالبة وارثة ببيع عني موروثة وقسمتها على‬\n ‫‪427‬‬     ‫الورثة‪ ،‬والورثة سوى املدعية خارج اململكة وال‬   ‫قسمة تركة‬   ‫‪25‬‬\n                      ‫يعرف محل إقامتهم‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":427,"source_page_end":433,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f7c12a1f9d342ab9d11c1bec33e16059eb28bc59cbb17199b4398bdf7476034d","normalized_text_hash":"3af56b726fb80f0fb866a694185997d1fef0b85b3b8f751809386d46f5c43535","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p427-34324097"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

