SELECT 'moj-all-verified-judgments-review-002-chunk-190' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"009cfcc2-3e17-522e-84f1-ec81b12c864d","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة املورث وترك عدة عقارات -مطالبة املدعي ببيع العقارات باملزاد العلني وتسليمه نصيبه منها -رأي هيئة النظر يف الدعوى -وجوب إجابة من طلب القسمة إلزالة ضرر الشركة -بيع العقار عند عدم إمكان قسمته بن الورثة -احلكم ببيع العقارات احملددة باملزاد العلني وتسليم كل وارث نصيبه الشرعي منها .","document_number":"34207864","case_number":"33226305","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/6","year":"1434","subject":"قسمة تركة -وفاة املورث وترك عدة عقارات -مطالبة املدعي ببيع العقارات باملزاد العلني وتسليمه نصيبه منها -رأي هيئة النظر يف الدعوى -وجوب إجابة من طلب القسمة إلزالة ضرر الشركة -بيع العقار عند عدم إمكان قسمته بن الورثة -احلكم ببيع العقارات احملددة باملزاد العلني وتسليم كل وارث نصيبه الشرعي منها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪34207864 :‬تاريخه‪1434/5/6 :‬هـ‬\n                  ‫رقم الدعوى‪33226305 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34328896‬تاريخه‪1434/10/12 :‬هـ‬\n\n\n‫قســمة تركــة‪ -‬وفــاة املــورث وتــرك عــدة عقــارات‪ -‬مطالبــة املدعــي ببيــع‬\n‫العقــارات باملــزاد العلنــي وتســليمه نصيبــه منهــا‪ -‬رأي هيئــة النظــر يف‬\n‫الدعــوى‪ -‬وجــوب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة‪ -‬بيــع‬\n‫العقــار عنــد عــدم إمــكان قســمته بــن الورثــة‪ -‬احلكــم ببيــع العقــارات‬\n     ‫احملــددة باملــزاد العلنــي وتســليم كل وارث نصيبــه الشــرعي منهــا ‪.‬‬\n\n\n\n\n‫يهــا؛ أ َْي ‪:‬‬  ‫يك ُه فِ َ‬  ‫جــاء يف مطالــب أولــى النهــى مــا نصــه ( َو َمـ ْـن َد َعــا َش ـ ِر َ‬\n‫اضــي إ َلــى َب ْيـ ٍـع أ ُْج ِبـ َـر َع َلــى ا ْل َب ْيـ ِـع َم َعـ ُه فَ ـ ِإ ْن َأ َبــى؛ أ َْي ‪ْ :‬ام َت َنـ َـع‬\n                                                                                                                   ‫قِ ْسـ َـم ِة ال َّت َر ِ‬\n‫اكـ ٌـم َع َل ْيهِ َمــا؛ َو َق َسـ َـم ال َّث َمـ َـن‬‫اع ـ ُه َح ِ‬     ‫يك ُه مِ ـ ْـن َب ْيـ ٍـع َم َع ـ ُه ِبيـ َـع أ َْي ‪َ :‬ب َ‬‫َش ـ ِر ُ‬\n                                                                    ‫َب ْي َن ُه َمــا َع َلــى َقــدْ ِر ِح َّص َت ْيهِ َمــا َن ًّصــا ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليهمــا أصالــة ووكالــة بــأن مورثتهــم‬\n‫التــي هــي والدتهــم توفيــت وانحصــر ورثتهــا يف زوجهــا ويف أوالدهــا منــه‬\n‫وجميعهــم بالغــون وتركــت عــدة عقــارات محــددة املعالــم واألوصــاف‬\n‫علــى النحــو املبــن ويطلــب احلكــم ببيــع هــذه العقــارات باملــزاد‬\n‫العلنــي وتســليمه نصيبــه منهــا هكــذا ادعــى‪ ،‬أجــاب املدعــى عليهــم‬\n‫أصالــة ووكالــة باملصادقــة علــى وفــاة مورثتهــم وانحصــار ورثتهــا يف‬\n\n                                                                                                                                               ‫‪408‬‬\n\f      ‫املذكوريــن وأنهــا قــد تركــت العقــارات املوصوفــة وال مانــع لديهــم مــن‬\n      ‫بيــع التركــة باملــزاد العلنــي وإعطــاء كل وارث نصيبــه منهــا‪ ،‬ليــس‬\n      ‫ـوص‪ ،‬جميــع الصكــوك مطابقــة لســجلها‬           ‫علــى مورثتهــم ديــون ولــم تـ ِ‬\n      ‫وســارية املفعــول حســب إفــادة كتابــة عــدل مكــة والطائــف‪ ،‬ثــم قــرر‬\n      ‫املدعــى عليهمــا رجوعهمــا عــن رغبتهمــا بيــع العقــارات باملــزاد ويطلبــان‬\n      ‫تثمينهــا فإمــا أن يشــتري املدعــي نصيبهــم مــن العقــارات أو يقومــون هــم‬\n      ‫بالشــراء هكــذا قــررا ‪ -‬وبعــرض ذلــك علــى املدعــي قــال أنــا أطلــب بيــع‬\n      ‫العقــارات يف املــزاد العلنــي هكــذا قــرر‪ ،‬جــرت الكتابــة لهيئــة النظــر‬\n      ‫يف احملكمــة مــن أجــل االجتمــاع بالطرفــن ومحاولــة اإلصــاح بينهمــا‬\n      ‫وتقديــر قيمــة العقــارات يف الوقــت الراهــن وهــل ميكــن قســمتها بــن‬\n      ‫الورثــة مــن دون ضــرر أو رد عــوض أو ال ؟ فــورد اجلــواب بــأن الصكــوك‬\n      ‫ال يوجــد بــه مســاحة كليــة وال ميكــن إجــراء الــازم‪ ،‬جــرى االطــاع‬\n      ‫علــى الــوكاالت وعلــى صكــوك العقــارات املشــار إليهــا بعاليــه‪ ،‬ونظــر ًا‬\n      ‫ملطابقــة صكــوك العقــارات لســجلها وســريان مفعولهــا وعــدم إضافــة‬\n      ‫املســاحة اإلجماليــة لبعــض الصكــوك ال مينــع مــن بيعهــا يف املــزاد العلني‬\n      ‫ال ســيما وأن عــدم إثبــات املســاحة بســبب مــا بــن الطرفــن مــن اخلــاف‬\n      ‫والشــقاق ولتعــذر اإلصــاح بــن الطرفــن ورغبــة املدعــي إعطــاءه حقــه‬\n      ‫الشــرعي مــن تركــة مورثتــه مــن العقــارات املذكــورة وألن أفضــل حــل‬\n      ‫هــو تنضيــض التركــة وإعطــاء كل وارث حقــه الشــرعي منهــا وحصول‬\n      ‫ذلك يف بيعها باملزاد العلني وألن لكل وارث حقا يف عني تركة مورثه‬\n      ‫وألنــه يصــار إلــى البيــع مــع عــدم إمــكان القســمة وحيــث قــرر الفقهــاء‬\n      ‫أنــه يجــب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة‪ ،‬ملــا تقــدم‬\n      ‫صــدر احلكــم ببيــع العقــارات احملــدودة بعاليــه باملــزاد العلنــي وتســليم‬\n\n\n‫‪409‬‬\n\f‫كل وارث نصيبــه الشــرعي منهــا‪ ،‬قــرر املدعــي القناعــة باحلكــم‬\n‫واعتــرض املدعــى عليهــم أصالــة ووكالــة بالئحــة‪ ،‬صــدق احلكــم بعــد‬\n‫مداولــة مــن الدائــرة احلقوقيــة اخلامســة مبحكمــة االســتئناف مبنطقــة‬\n                                                      ‫مكــة املكرمــة ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فلــدي‬\n‫أنــا ‪ .........‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمــة برقــم ‪ 33226305‬وتاريــخ ‪ 1433/03/30‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33534987‬وتاريــخ ‪ 1433/03/21‬ه ـ ففــي يــوم‬\n‫االثنــن ‪1433/8/12‬ه ـ افتتحــت اجللســة الســاعة الثامنــة صباحـ ًا للنظر‬\n‫يف دعــوى ‪.........‬ضــد ورثــة ‪ .........‬وفيهــا حضــر املدعــي ‪.........‬د ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬وحضــر حلضــوره ‪.........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقم‪.........‬باألصالــة عــن نفســه‬\n‫وبالوكالــة عــن ‪.........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الطائــف الثانيــة‬\n‫برقــم ‪ 25481‬يف ‪1433/5/3‬ه ـ جلــد ‪ 5762‬واملخــول لــه يف الوكالــة‬\n‫حــق إقامــة وســماع الدعــاوى منــه أو ضــده واملرافعــة واملدافعــة وحضــور‬\n‫اجللســات وتقــدمي البينــات وســماعها وســماع احلكــم وقبولــه والقناعــة بــه‬\n‫مــن عدمهــا ويف اجلــرح والتعديــل والطعــن االســتئناف والتمييــز ويف‬\n‫اإلقــرار واإلنــكار وتوريــد الشــهود وطلــب حتليــف اليمــن ‪...‬الــخ‬\n‫وبالوكالــة عــن ‪.........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n\n                                                                                     ‫‪410‬‬\n\f      ‫‪.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة بالطائــف‬\n      ‫برقــم ‪ 25603‬يف ‪1433/5/3‬ه ـ جلــد ‪ 5764‬واملخــول لــه يف الوكالــة‬\n      ‫حــق إقامــة وســماع الدعــاوى منــه أو ضــده واملرافعــة واملدافعــة وحضــور‬\n      ‫اجللســات وتقــدمي البينــات وســماعها وســماع احلكــم وقبولــه والقناعــة بــه‬\n      ‫مــن عدمهــا ويف اجلــرح والتعديــل والطعــن االســتئناف والتمييــز ويف‬\n      ‫اإلقــرار واإلنــكار وتوريــد الشــهود وطلــب حتليــف اليمني‪...‬الــخ‬\n      ‫وبالوكالــة عــن ‪.........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بغــرب‬\n      ‫مكــة برقــم ‪ 32265645‬يف ‪1432/10/16‬ه ـ واملخــول لــه يف الوكالــة‬\n      ‫حــق إقامــة وســماع الدعــاوى منــه أو ضــده واملرافعــة واملدافعــة وحضــور‬\n      ‫اجللســات وتقــدمي البينــات وســماعها وســماع احلكــم وقبولــه والقناعــة بــه‬\n      ‫مــن عدمهــا ويف اجلــرح والتعديــل والطعــن االســتئناف والتمييــز ويف‬\n      ‫اإلقــرار واإلنــكار وتوريــد الشــهود وطلــب حتليــف اليمــن ‪...‬الــخ‬\n      ‫وبالوكالة‪.........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪.........‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة‬\n      ‫برقــم ‪ 13605‬يف ‪1431/4/22‬ه ـ واملخــول لــه يف الوكالــة حــق إقامــة‬\n      ‫وســماع الدعــاوى منــه أو ضــده واملرافعــة واملدافعــة وحضــور اجللســات‬\n      ‫وتقــدمي البينــات وســماعها وســماع احلكــم وقبولــه والقناعــة بــه مــن‬\n      ‫عدمهــا ويف اجلــرح والتعديــل والطعــن االســتئناف والتمييــز ويف اإلقــرار‬\n      ‫واإلنــكار وتوريــد الشــهود وطلــب حتليــف اليمــن ‪...‬الــخ كمــا حضــر‬\n      ‫‪.........‬ســعودي اجلنســية مبوجــب الســجل رقــم ‪.........‬باألصالــة عــن نفســه‬\n      ‫وبالوكالــة عــن ‪.........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪.........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بغــرب‬\n\n\n‫‪411‬‬\n\f‫مكــة برقــم ‪ 33109483‬يف ‪1433/3/1‬ه ـ واملخــول لــه يف الوكالــة‬\n‫حــق مراجعــة احملاكــم الشــرعية وكتابــة العــدل واجلهــات ذات العالقــة‬\n‫‪...‬الــخ واملدعــي واملدعــى عليهــم أصالــة ووكالــة هــم جميعـ ًا ورثــة ‪.........‬‬\n‫مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ 7‬يف‬\n‫ا يف دعــواه‪ :‬لقــد توفيــت مورثتنــا‬           ‫‪1428/8/21‬ه ـ فادعــى املدعــي قائ ـ ً‬\n‫والدتــي ‪.........‬بتاريــخ ‪1428/8/13‬ه ـ وانحصــر ورثتهــا يف زوجهــا ‪.........‬‬\n‫ويف أوالدهــا منــه أنــا ‪......... ......... ......... ......... ......... ......... .........‬‬\n‫وجميعنــا بالغــون وذلــك مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 7‬يف ‪1428/8/21‬ه ـ وتركــت العقــارات التاليــة‪ :‬أو ًال‬\n‫‪ :‬العقــار الكائــن مبكــة املكرمــة مبحلــة جــرول العتيبيــة احملــدود‬\n‫شــرق ًا بالســكة النافــذة وبهــا واجهــة الــدار والبــاب وغربـ ًا ملــك شــديد‬\n‫احلربــي وشــام ًا ملــك ‪.........‬ومين ـ ًا الرحبــة العامــة وبهــا واجهــة الــدكان‬\n‫والبــاب املذروعــة طــو ًال مــن الشــام إلــى اجلنــوب ممــا يلــي الشــرق والغــرب‬\n‫ثالثــة عشــر متــر ًا وعرضـ ًا مــن الشــرق إلــى الغــرب ممــا يلــي الشــام تســعة‬\n‫أمتــار وتســعون ســنتيمتر وممــا يلــي اجلنــوب خمســة أمتــار وســبعون‬\n‫ســنتمترا وعــرض الســكة الشــرقية النافــذة ممــا يلــي الشــام عشــرة‬\n‫أمتــار وعشــرون ســنتمترا وممــا يلــي اجلنــوب عشــرة أمتــار وســتون‬\n‫ســنتيمترا وعــرض الرحبــة اجلنوبيــة العامــة ممــا يلــي الشــرق مــن هــذا‬\n‫احملــدود إلــى ركــن دار ‪.........‬أربعــة عشــر متــر ًا وعشــرة ســنتيمتر ًا وممــا‬\n‫يلــي الغــرب مــن هــذا احملــدود إلــى ركــن حــوش البشــناق ثمانيــة عشــر‬\n‫متــر ًا وعشــرة ســنتيمترات اململــوك لهــا مبوجــب الصــك الصــادر مــن‬\n‫كتابــة عــدل مكــة املكرمــة برقــم ‪ 1/724‬يف ‪1395/6/29‬ه ـ ثاني ـاً‪:‬‬\n‫العقــار الكائــن مبكــة املكرمــة الواقــع بجــرول املشــعلية مــن محلــة‬\n\n\n                                                                                                  ‫‪412‬‬\n\f      ‫الهنداويــة املــذروع مــن الشــرق إلــى الغــرب ممــا يلــي الشــام واليمــن ســتة‬\n      ‫عشــر متــر ًا وممــا يلــي الشــرق خمســة عشــر متــرا وثالثــون ســنتيمتر ًا‬\n      ‫وممــا يلــي الغــرب تســعة أمتــار يحــده شــرق ًا ملــك ‪ .........‬وغرب ـ ًا وشــام ًا‬\n      ‫طريــق عرضــه خمســة أمتــار وجنوب ـ ًا الشــريف ‪ .........‬واململــوك لهــا‬\n      ‫مبوجــب الصــك الصــادر مــن كتابــة عــدل مكــة املكرمــة برقــم ‪1023‬‬\n      ‫يف ‪1406/10/20‬ه ـ ثالث ـاً‪ :‬العقــار الكائــن مبكــة املكرمــة الواقــع‬\n      ‫بجــرول باملشــعلية مــن محلــة ‪ .........‬وذرعــه مــن الشــرق ملــك ‪.........‬وغربـ ًا‬\n      ‫وشــام ًا الطريــق عرضــه خمســة أمتــار وجنوب ـ ًا الشــريف ‪.........‬املذروعــة‬\n      ‫مــن الشــام إلــى اليمــن ممــا يلــي الشــرق ثالثــة عشــر متــر ًا وممــا يلــي‬\n      ‫الغــرب تســعة أمتــار ومــن الشــرق للغــرب ممــا يلــي الشــام ثمانيــة أمتــار‬\n      ‫ونصــف وممــا يلــي اليمــن ثمانيــة أمتــار اململــوك لهــا مبوجــب الصــك‬\n      ‫الصــادر مــن كتابــة عــدل مكــة املكرمــة برقــم ‪ 1310‬يف‬\n      ‫‪1406/10/20‬ه ـ رابع ـاً‪ :‬العقــار الكائــن بحــي الشــهداء القدميــة‬\n      ‫بالطائــف وحــدود وذرعــه كمــا يلــي‪ :‬شــرق ًا وغرب ـ ًا اثنــا عشــر متــر ًا‬\n      ‫وعشــرون ســنتيمتر والضلــع الشــمالي ســبعة متــر وثمانــون ســنتيمتر‬\n      ‫واجلنــوب ســبعة متــر وخمســون ســنتيمتر يحدهــا شــرق ًا الشــاع العــام‬\n      ‫وغربـ ًا ملــك ‪ .........‬وشــما ًال ملــك ‪ ......‬وجنوبـ ًا ‪.........‬اململــوك لهــا مبوجــب‬\n      ‫الصــك الصــادر مــن كتابــة العــدل األولــى بالطائــف برقــم ‪2/4/190‬‬\n      ‫يف ‪1414/9/19‬ه ـ أطلــب احلكــم ببيــع العقــارات باملــزاد العلنــي‬\n      ‫وتســليمي نصيبــي منهــا هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليهــم أصالــة ووكالــة أجابــا قائلــن‪ :‬مــا ذكــره املدعــي يف دعــواه مــن‬\n      ‫وفــاة مورثتنــا ‪ .....‬وانحصــار ورثتهــا يف املذكوريــن مبوجــب صــك حصــر‬\n      ‫ورثتهــا وأننــا جميعـ ًا بالغــون وأنهــا قــد تركت العقــارات األربع املوصوفة‬\n\n\n‫‪413‬‬\n\f‫أعــاه فهــذا كلــه صحيــح وال مانــع لدينــا جميع ـ ًا مــن بيــع التركــة‬\n‫باملــزاد العلنــي وإعطــاء كل وارث نصيبــه منهــا هكــذا أجابــا وقــررا‬\n‫فجــرى ســؤال الطرفــن هــل ملورثتكــم املتوفــاة ‪.........‬وصيــة أو عليهــا‬\n‫ديــون؟ فأجابــا بالنفــي بأنهــا لــم تــوص وليــس عليهــا ديــون هكــذا قــرروا‬\n‫ولالستفســار عــن صكــوك العقــارات مــن مصادرهــا لبيــان مطابقتهــا‬\n‫لســجلها وســريان مفعولهــا فقــد رفعــت اجللســة إلــى يــوم الثالثــاء‬\n‫‪1433/11/16‬ه ـ الســاعة العاشــرة والنصــف صباحـ ًا ‪ ،‬وبــاهلل التوفيــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n‫‪1433/8/12‬ه ـ ثــم إنــه يف يــوم الثالثــاء ‪1433/11/16‬ه ـ الســاعة‬\n‫العاشــرة والنصــف صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وحضــر حلضــوره املدعــى عليــه أصالــة ووكالــة ‪.........‬واملدعــى عليــه‬\n‫أصالــة ووكالــة ‪.........‬وكان قــد جــرت الكتابــة منــي لكتابــة العــدل‬\n‫األولى مبكة املكرمة باخلطاب رقم ‪ 331531943‬يف ‪1433/8/13‬هـ‬\n‫مــن أجــل االستفســار عــن الصك رقــم ‪ 1/724‬يف ‪1395/6/29‬هـ فوردنا‬\n‫اجلــواب برقــم ‪ 331549738‬يف ‪1433/9/13‬ه ـ مفــاده بــأن صــور الصــك‬\n‫رقــم ‪ 1/724‬يف ‪1395/6/29‬ه ـ مطابقــة لســجلها وســارية املفعــول حتــى‬\n‫تاريخــه أ‪ .‬ه ـ والكتابــة منــي لكتابــة العــدل األولــى مبكــة املكرمــة‬\n‫باخلطــاب رقــم ‪ 331531944‬يف ‪1433/8/13‬ه ـ مــن أجــل االستفســار‬\n‫عــن الصــك رقــم ‪ 1023‬يف ‪1380/10/17‬ه ـ فوردنــا اجلــواب برقــم‬\n‫‪ 331551035‬يف ‪1433/9/10‬ه ـ مفــاده بــأن صــور الصــك رقــم ‪1023‬‬\n‫يف ‪1380/10/17‬ه ـ مطابقــة لســجلها وســارية املفعــول حتــى تاريخــه أ‪.‬‬\n‫ه ـ والكتابــة منــي لكتابــة العــدل األولــى مبكــة املكرمــة باخلطــاب‬\n‫رقــم ‪ 331531941‬يف ‪1433/8/13‬ه ـ مــن أجــل االستفســار عــن الصــك‬\n\n\n                                                                                    ‫‪414‬‬\n\f      ‫رقــم ‪ 1310‬يف ‪1388/8/27‬ه ـ فوردنــا اجلــواب برقــم ‪ 331549777‬يف‬\n      ‫‪1433/9/13‬ه ـ مفــاده بــأن صــور الصــك رقــم ‪ 1310‬يف ‪1388/8/27‬ه ـ‬\n      ‫مطابقــة لســجلها وســارية املفعــول حتــى تاريخــه أ‪ .‬ه ـ والكتابــة منــي‬\n      ‫لكتابــة العــدل األولــى مبحافظــة الطائــف باخلطــاب رقــم ‪331531942‬‬\n      ‫يف ‪1433/8/13‬ه ـ مــن أجــل االستفســار عــن الصــك رقــم ‪ 2/4/190‬يف‬\n      ‫‪1414/9/19‬ه ـ فوردنــا اجلــواب برقــم ‪ 5407‬يف ‪1433/9/16‬ه ـ مفــاده‬\n      ‫بــأن صــور الصــك رقــم ‪ 2/4/190‬يف ‪1414/9/19‬ه ـ مطابقــة لســجلها‬\n      ‫وســارية املفعــول حتــى تاريخــه أ‪ .‬ه ـ ثــم قــرر املدعــى عليهمــا بقولهمــا لقــد‬\n      ‫أوضحنــا يف اجللســة املاضيــة رغبتنــا بيــع العقــارات يف املــزاد العلنــي ولــم‬\n      ‫نكــن نعلــم حقيقــة املــزاد وكنــا نظــن أن املقصــود تثمينهــا ونحــن نطلب‬\n      ‫تثمينهــا فإمــا أن يشــتري املدعــي نصيبنــا مــن العقــارات أو نقــوم نحــن‬\n      ‫بالشــراء هــذا مــا لدينــا هكــذا قــررا وبعــرض ذلــك علــى املدعــي قــال أنا‬\n      ‫أطلــب بيــع العقــارات يف املــزاد العلنــي هكــذا قــرر عنــد ذلــك قــررت‬\n      ‫الكتابــة لهيئــة النظــر يف احملكمــة مــن أجــل االجتمــاع بالطرفــن‬\n      ‫ومحاولــة اإلصــاح بينهمــا وتقديــر قيمــة العقــارات يف الوقــت الراهــن‬\n      ‫وهــل ميكــن قســمتها بــن الورثــة مــن دون ضــرر أو رد عــوض أو ال ؟‬\n      ‫وإفادتنــا بذلــك ورفعــت اجللســة لذلــك‪ ،‬ثــم إنــه يف يــوم االثنــن‬\n      ‫‪1434/5/6‬ه ـ افتتحــت اجللســة الســاعة الواحــدة ظهــرا وفيهــا حضــر‬\n      ‫املدعــي وحضــر حلضــوره املدعــى عليــه أصالــة ووكالــة ‪.........‬واملدعــى‬\n      ‫عليــه أصالــة ووكالــة ‪.........‬وكان قــد جــرت الكتابــة منــي لهيئــة‬\n      ‫النظــر يف احملكمــة مــن أجــل االجتمــاع بالطرفــن ومحاولــة اإلصــاح‬\n      ‫بينهمــا وتقديــر قيمــة العقــارات يف الوقــت الراهــن وهــل ميكــن قســمتها‬\n      ‫بــن الورثــة مــن دون ضــرر أو رد عــوض أو ال ؟ وذلــك مبوجــب خطابنــا‬\n\n\n‫‪415‬‬\n\f‫رقــم ‪ 33534987‬يف ‪1433/11/17‬ه ـ فوردنــا اجلــواب منهــم برقــم‬\n‫‪ 33534987‬يف ‪1434/2/25‬ه ـ وبرفقــه قرارهــم املــؤرخ يف‬\n‫‪1434/2/25‬ه ـ املتضمــن بعــد املقدمــة مــا نصه ‪ « :‬عليه فقد مت الوقوف‬\n‫علــى العقــارات ولــم جنــد مســاحات كليــة يف الصكــوك وال ميكــن‬\n‫إجــراء الــازم إال بوجــود مســاحات كليــة هــذا ما جرى تقريره والســام‬\n‫« عضــوا هيئــة النظــر ‪.........‬توقيعــه ‪.........‬توقيعــه عنــد ذلــك جــرى ســؤال‬\n‫الطرفــن عــن ســبب عــدم إضافــة املســاحة اإلجماليــة يف الصكــوك ؟‬\n‫فقــاال ‪ :‬إن العقــار الواقــع يف العتيبيــة فيــه إثبــات مســاحة وهــو داخــل‬\n‫ضمــن مشــروع األمانــة إلزالتــه لغــرض توســعة الشــارع أمــا بقيــة‬\n‫الصكــوك فــا ومبناقشــة الطرفــن عــن ســبب ذلــك فــكل واحــد منهــم‬\n‫يلقــي بالالئمــة علــى اآلخــر وأنــه هــو مــن وراء التعطيــل يف ذلــك وظهــر‬\n‫لــي الشــقاق واخلــاف بــن الطرفــن ممــا تعــذر معــه اإلصــاح بينهــم ومــن‬\n‫خــال احلديــث بــن الطرفــن تبــن أن هنــاك قضيــة عقــوق مقامــة مــن‬\n‫والــد املدعــي عليــه كمــا جــرى منــي االطــاع علــى صــك حصــر ورثــة‬\n‫‪.........‬واملتضمــن وفاتهــا بتاريــخ ‪1428/8/13‬ه ـ وانحصــار ورثتهــا يف‬\n‫زوجهــا ‪.........‬ويف أوالدهــا منــه ط‪......... ......... ......... ......... ......... .........‬‬\n‫‪.........‬ر‪ .........‬وجميعهــم بالغــون وذلــك مبوجــب صــك حصــر الورثــة‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 7‬يف ‪1428/8/21‬ه ـ كمــا جــرى‬\n‫االطــاع علــى الــوكاالت وعلــى صكــوك العقــارات املشــار إليهــا بعاليه‬\n‫فوجــد تتضمــن مطابقتهــا ملــا عطــف عليهــا فجــرى ســؤال الطرفــن هــل‬\n‫لديكمــا مــا تريــدان إضافتــه ؟ فقــاال ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه‬\n‫ونطلــب الفصــل يف القضيــة هكــذا قــررا فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وبعــد دراســة القضيــة وتأملهــا وبعــد االطــاع علــى‬\n\n\n                                                                                                    ‫‪416‬‬\n\f      ‫لفــات املعاملــة وعلــى الصكــوك املشــار إليهــا بعاليــه ونظــرا ملطابقــة‬\n      ‫صكــوك العقــارات لســجلها وســريان مفعولهــا وعــدم إضافــة املســاحة‬\n      ‫اإلجماليــة لبعــض الصكــوك ال مينــع مــن بيعهــا يف املــزاد العلنــي ال ســيما‬\n      ‫وأن عــدم إثبــات املســاحة بســبب مــا بــن الطرفــن مــن اخلــاف والشــقاق‬\n      ‫ولتعــذر اإلصــاح بــن الطرفــن ورغبــة املدعــي إعطــاءه حقــه الشــرعي‬\n      ‫مــن تركــة مورثتــه مــن العقــارات املذكــورة وألن أفضــل حــل هــو‬\n      ‫تنضيــض التركــة وإعطــاء كل وارث حقــه الشــرعي منهــا وحصــول‬\n      ‫ذلــك يف بيعهــا باملــزاد العلنــي وألن لــكل وارث حقــا يف عــن تركــة‬\n      ‫مورثــه وألنــه يصــار إلــى البيــع مــع عــدم إمــكان القســمة وحيــث قــرر‬\n      ‫الفقهــاء أنــه يجــب إجابــة مــن طلــب القســمة إلزالــة ضــرر الشــركة قــال‬\n      ‫يك ُه فِ ي َهــا؛ َأ ْي ‪ :‬قِ ْسـ َـم ِة‬      ‫يف مطالــب أولــى النهــى مــا نصــه « َو َمــنْ َد َعــا َشـ ِـر َ‬\n      ‫يك ُه‬  ‫اضــي إ َلــى َب ْيـ ٍـع ُأ ْج ِبـ َـر َع َلــى ا ْل َب ْيـ ِـع َم َعـ ُه َفـ ِإنْ َأ َبــى؛ َأ ْي ‪ْ :‬ام َت َنـ َـع َشـ ِـر ُ‬\n                                                                                                                                        ‫ال َّت َر ِ‬\n                                                                                   ‫اعـ ُه َح ِ‬\n      ‫اكـ ٌـم َع َل ْيه َِمــا؛ َوقَ َسـ َـم الث ََّمـ َـن َب ْي َن ُه َمــا َع َلــى‬              ‫مِ ــنْ َب ْيـ ٍـع َم َعـ ُه ِبيـ َـع َأ ْي ‪َ :‬ب َ‬\n      ‫َصــا « لذلــك كلــه فقــد حكمــت ببيــع العقــارات‬                                                      ‫قَ ــدْ ِر حِ َّص َت ْيه َِمــا ن ًّ‬\n      ‫احملــدودة بعاليــه باملــزاد العلنــي وتســليم كل وارث نصيبــه الشــرعي‬\n      ‫منهــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة بــه واملدعــى‬\n      ‫عليهــم أصالــة ووكالــة عــدم القناعــة وطلبــوا االســتئناف بالئحــة‬\n      ‫اعتراضيــة فجــرى إفهامهــم بــأن عليهــم التقــدم للمحكمــة يــوم االثنــن‬\n      ‫القــادم ‪1434/5/13‬ه ـ الســتالم نســخة مــن صــك احلكــم لتقــدمي‬\n      ‫اعتراضهــم عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وإذا لــم‬\n      ‫يتقدمــوا بذلــك خــال املــدة املذكــورة فسيســقط حقهــم بطلــب‬\n      ‫االســتئناف وسيكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى‬\n          ‫اهلل على نينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/5/6‬هـ‬\n\n\n‫‪417‬‬\n\f‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األربعــاء ‪1434/9/9‬ه ـ افتتحــت‬\n‫اجللســة وكان قــد جــرى بعــث املعاملــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة ثــم عــادت إلينــا بخطــاب فضيلــة رئيــس محكمــة االســتئناف‬\n‫مبكــة املكرمــة املكلــف برقــم ‪ 33534987‬يف ‪1434/7/29‬ه ـ‬\n‫وبرفقــه قــرار الدائــرة احلقوقيــة اخلامســة برقــم ‪ 34274606‬يف‬\n‫‪1434/7/22‬ه ـ املتضمــن بعــد املقدمــة مــا نصــه ‪ :‬وبدراســة احلكــم‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا‬\n‫حيــث ورد يف الالئحــة االعتراضيــة مــا يوجــب إعــادة النظــر بحضــور‬\n‫الطرفــن ومناقشــتها دفعــا للضــرر ومحاولــة الصلــح قــدر املســتطاع‪.‬‬\n‫واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫قاضــي اســتئناف ‪.........‬توقيعــه ختمــه الشــخصي قاضي اســتئناف ‪.........‬‬\n‫توقيعــه ختمــه الشــخصي رئيــس الدائــرة ‪.........‬توقيعــه ختمــه الشــخصي‬\n‫أ‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم للعلــم النافــع‬\n‫والعمــل الصالــح بأنــه ســبق وأن اطلعــت علــى الالئحــة االعتراضيــة ولــم‬\n‫أجــد فيهــا مــا يؤثــر علــى مــا حكمت به وجــرى التنويه عليهــا بذلك وبني‬\n‫املدعــي واملدعــى عليهــم مــن الشــقاق والنــزاع مــا يتعــذر معــه اإلصــاح‬\n‫واألســلم يف ذلــك كلــه هــو بيــع التركــة يف املــزاد العلنــي وتســليم كل‬\n‫وارث نصيبــه الشــرعي منهــا لذلــك وبعــد اإلجابــة لــم يظهــر لــي ســوى‬\n‫مــا أجريتــه‪ ،‬وأمــرت بإحلــاق ذلــك يف صكــه وســجله‪ ،‬وإعــادة املعاملــة‬\n‫حملكمــة االســتئناف إلكمــال الزمهــا‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n   ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/9/9‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n\n\n                                                                                 ‫‪418‬‬\n\f      ‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪.........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n      ‫املســجل بعــدد ‪ 34207864‬وتاريــخ ‪1434/05/06‬ه ـ املتضمــن دعــوى‬\n      ‫‪.........‬ضــد ورثــة ‪.........‬في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم‬\n      ‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــرر املوافق ــة عل ــى احلكــم بعــد‬\n      ‫اإليضــاح االخيــر وبــاهلل التوفيــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى‬\n                                                                 ‫آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪419‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":408,"source_page_end":419,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"09a2e7ea74071561e9e126a842cfb231ea680bffc76aa6cd8864f316ed639d3a","normalized_text_hash":"c4f4086c1f0ed7868fb6648b1d210908c58f8d79713f717860fbe3b9cb50ae6b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p408-34207864"},{"id":"a8a1193a-3560-557e-88d7-11f744f0db7c","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -وفاة مورث وترك تركة -مطالبة املدعية بإجراء القسمة الشرعية وأخذ نصيبها من التركة -عدم وجود بينة للمدعية -رفض مين املدعى عليه -صرف النظر عن الدعوى- إفهام املدعية بعد احلكم بأن لها مين املدعى عليه متى أرادت .","document_number":"34225205","case_number":"33193324","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف اخللف للشيخ","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/28","year":"1434","subject":"قسمة تركة -وفاة مورث وترك تركة -مطالبة املدعية بإجراء القسمة الشرعية وأخذ نصيبها من التركة -عدم وجود بينة للمدعية -رفض مين املدعى عليه -صرف النظر عن الدعوى- إفهام املدعية بعد احلكم بأن لها مين املدعى عليه متى أرادت .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34225205 :‬تاريخه‪1434/5/28 :‬هـ‬\n                  ‫رقم الدعوى‪33193324 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34252426‬تاريخه‪1434/6/26 :‬هـ‬\n\n\n‫قســمة تركــة‪ -‬وفــاة مــورث وتــرك تركــة‪ -‬مطالبــة املدعيــة بإجــراء‬\n‫القســمة الشــرعية وأخــذ نصيبهــا مــن التركــة‪ -‬عــدم وجــود بينــة‬\n‫للمدعيــة‪ -‬رفــض ميــن املدعــى عليــه‪ -‬صــرف النظــر عــن الدعــوى‪-‬‬\n‫إفهــام املدعيــة بعــد احلكــم بــأن لهــا ميــن املدعــى عليــه متــى أرادت ‪.‬‬\n\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                     ‫أنكــر)‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه بــأن مورثهــم قــد تــويف قبــل ثالثــن‬\n‫عامـ ًا وخلــف بيتـ ًا يف حــي ‪ .....‬بالطائــف وبيتــن يف ‪ .....‬ومنــزل شــعبي يف‬\n‫‪ .....‬ومنــزل مســلح يف ‪ .....‬وليــس عليهــا صكــوك شــرعية وتطلــب إجــراء‬\n‫القســمة بينهمــا هكــذا ادعــت‪ ،‬أجــاب املدعــى عليــه باإلنــكار وأن‬\n‫مورثهــم لــم يخلــف بيتــا يف حــي ‪ .....‬وأنــه قــد خلــف منــز ًال شــعبي ًا يف قريــة‬\n‫‪ .....‬وليــس عليــه صــك شــرعي وأمــا املنــزل يف ‪ .....‬فهــو ملكــه ويطلــب رد‬\n‫الدعــوى هكــذا أجــاب‪ ،‬أنكــرت املدعيــة مــا أجــاب بــه املدعــى عليــه‬\n‫وليــس لديهــا بينــة علــى دعواهــا وال تطلــب ميــن املدعــى عليــه علــى نفــي‬\n‫دعواهــا‪ ،‬لقولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــي واليمــن‬\n\n                                                                                            ‫‪420‬‬\n\f      ‫علــى مــن أنكــر )‪ ،‬صــدر احلكــم بصــرف النظــر عــن دعــوى املدعيــة‪،‬‬\n      ‫وإفهامهــا بــأن لهــا ميــن املدعــى عليــه متــى مــا أرادت‪ ،‬قنــع املدعــى‬\n      ‫عليــه باحلكــم واعترضــت املدعيــة بالئحة‪،‬صــدق احلكــم مــن الدائــرة‬\n            ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنا ‪ ...‬القاضي يف احملكمة العامة بالطائف‬\n      ‫اخللــف للشــيخ ‪ ...‬ففــي هــذا اليــوم يف هــذا اليوم اإلثنــن ‪1434/05/27‬هـ‬\n      ‫افتتحت اجللســة يف متام الســاعة احلادية عشــر صباحا جرى االطالع على‬\n      ‫مــا ضبــط ســابقا بخصــوص دعــوى ‪ ...‬ســعودية اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬ضــد ‪ ...‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪ ...‬واملتضمــن‬\n      ‫مــا نصــه (احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي يف احملكمــة‬\n      ‫العامــة بالطائــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالطائــف برقــم ‪ 33193324‬وتاريــخ ‪1433/03/19‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33512142‬وتاريــخ ‪1433/03/19‬ه ـ ففــي‬\n      ‫يــوم الســبت ‪1433/05/15‬ه ـ افتتحــت اجللســة يف متــام الســاعة ‪: 08‬‬\n      ‫‪ 10‬صباحــا وفيهــا حضــرت املــرأة املدعيــة ‪ ...‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه ‪ ...‬ولــم يقــدم عــذرا‬\n      ‫لتخلفــه عــن هــذه اجللســة ولــم يتقــدم وكيــل عنــه وقــد مت بعــث تبليــغ‬\n      ‫لــه عــن طريــق محضــر اخلصــوم بهــذه احملكمــة برقــم ‪ 33520178‬يف‬\n      ‫‪1433/3/19‬ه ـ وقــد أفادنــا احملضــر بهــذه احملكمــة ‪ ...‬واملتضمــن بــأن‬\n      ‫املدعــى عليــه قــد تبلــغ بنفســه باملوعــد احملــدد فعليــه وبنــاء علــى املــادة‬\n\n‫‪421‬‬\n\f‫(‪ )55‬مــن نظــام املرافعــات الشــرعية فقــد قــررت نظــر دعــوى املدعــي يف‬\n‫غيــاب املدعــى عليــه وســألت املدعيــة عــن دعواهــا فقالــت اطلــب املهلــة‬\n‫لتحريــر دعــواي هكــذا قــررت ثــم أفهمــت املدعيــة بــأن عليهــا إحضــار‬\n‫صــك حصــر الورثــه وصكــوك العقــارات وإحضــار محــرم لهــا ففهمــت‬\n‫ذلــك ثــم رفعــت اجللســة ويف هــذا اليــوم االحــد ‪1433/6/8‬ه ـ افتتحــت‬\n‫اجللســة يف متــام الســاعة العاشــرة والنصــف صباحــا وفيهــا حضــرت املــرأة‬\n‫املدعيــة ‪ ...‬املدونــة هويتهــا ســابقا وحضــر حلضورهــا املدعــى عليــه ‪... ...‬‬\n‫يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪ ...‬وادعــت املدعيــة علــى املدعــى عليــه‬\n‫قائلــة يف دعواهــا ان مورثــي ومــورث املدعــى عليــه هــذا احلاضــر‪ ...‬قــد‬\n‫تــويف قبــل ثالثــن عامــا وقــد خلــف مورثنــا بيــت بالطائــف حــي ‪ .....‬كمــا‬\n‫خلــف بيتــن يف ‪ .....‬منــزل شــعبي بقريــة ‪ .....‬ومنــزل مســلح يف ‪ .....‬وليــس‬\n‫يف اجلميــع صكــوك شــرعية واطلــب اجــراء القســمة بيننــا حســب الشــرع‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه عــن دعــوى املدعيــة اجــاب قائــا‬\n‫كل مــا ذكرتــه مــن أن مورثنــا قــد تــويف فصحيــح أمــا مــا ذكــرت بأنــه‬\n‫خلــف بيــت يف الطائــف حــي ‪ .....‬فليــس بصحيــح وامنــا خلــف منــزل شــعبي‬\n‫يف قريــة ‪ .....‬وليــس عليــه صــك شــرعي أمــا بالنســبة للمنــزل الــذي يف‬\n‫قريــة ‪ .....‬فهــو ملــك لــي وهنــاك دعــوى أقيمــت لــدى فضيلــة الشــيخ ‪...‬‬\n‫ولــذا اطلــب رد دعــوى املدعيــة هكــذا أجــاب وبعــرض ذلــك علــى املــرأة‬\n‫املدعيــة قالــت كل مــا ذكــره غيــر صحيح والصحيــح ما جاء يف دعواي‬\n‫وأطلــب املهلــة إلحضــار البينــة هكــذا قــررت وأفهــم الطرفــن بــأن‬\n‫عليهــم إحضــار صــك حصــر ورثــة لوالدهــم وكذلــك تبليــغ لبقيــة الورثــة‬\n‫وســيتم االستفســار مــن فضيلــة الشــيخ القائــم بعمــل املكتــب القضائــي‬\n‫التاســع لإلفــادة عــن الدعــوى التــي لديهــم بخصــوص الطرفــن ويف يــوم‬\n\n\n                                                                                      ‫‪422‬‬\n\f      ‫األحــد ‪1433/10/15‬ه ـ حضــرت املدعيــة ‪ ...‬املدونــة هويتهــا ولــم يحضر‬\n      ‫املدعــى عليــه ‪ .....‬وقــد تبلــغ مبوعــد اجللســة يف اجللســة املاضيــة فعليــه‬\n      ‫وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية فقــد‬\n      ‫قــررت االســتمرار يف نظــر دعــوى املدعيــة يف غيــاب املدعــى عليــه فجــرى‬\n      ‫ســؤال املــرأة هــل لديــك البينــة علــى صحــة دعــواك فقالــت ليــس لــدي‬\n      ‫بينــة يف الوقــت احلالــي واملدعــى عليــه لــم يحضــر وســوف أبحــث عــن‬\n      ‫بينــة يف اجللســة القادمــة هكــذا أجابــت هــذا كمــا ورد الينــا خطــاب‬\n      ‫مــن القائــم بعمــل املكتــب القضائــي التاســع برقــم ‪33/1107125‬‬\n      ‫يف ‪1433/08/03‬ه ـ واملتضمــن (بخصــوص دعــوى ‪ ...‬ضــد ‪ ...‬وطلــب‬\n      ‫االفــادة عــن الســابقة املوجــودة نفيدكــم بأنــه لــم يراجــع طــريف الدعــوى‬\n      ‫وبالبحــث لــم جنــد شــيء مــدون يف الضبوط)أ‪.‬ه ـ ثــم أضافــت املدعيــة‬\n      ‫قائلــة بــأن مورثنــا قــد خلــف مزرعــة يف أبــي اجلمــام يف معــاة الصــار‬\n      ‫وبئريــن يف الصــار وركيــب حبــاس وجبــل البــارك وركيــب جــر الســيل‬\n      ‫والشــرما وهــو ثالثــة أقســام وأطلــب إحضــار املدعــى عليــه وســماع مــا‬\n      ‫لديــه هكــذا قــرر فعليــه فقــد أجبتهــا لطلبهــا ثــم رفعــت اجللســة ويف يــوم‬\n      ‫األربعــاء املوافــق‪ 1433/11/17‬ه ـ حضــرت املــرأة املدعيــة ‪ ...‬واملدونــة‬\n      ‫هويتهــا ســابقا وحضــر حلضورهــا املدعــى عليــة ‪ ...‬واملدونــة هويتــه‬\n      ‫ســابقا فجــرى ســؤال املدعــى عليــه عــن ســبب تأخــره وعــدم حضــوره‬\n      ‫يف اجللســات املاضيــة فقــال اننــي مريــض بأمــراض متعــددة منهــا مــرض‬\n      ‫الســكر والبرســتات ولــن أتأخــر مــرة اخــرى هكــذا قــرر فجــرى ســؤال‬\n      ‫املدعــى عليــه هــل احضــرت حصــر الورثــة وصــك العقــار فقــال ليــس لدي‬\n      ‫اي صــك ولــم اخــرج اي شــيء ســوى ان لــدي وثيقــة علــى املنــزل الواقــع يف‬\n      ‫الصــار واملنــزل الواقــع يف مدغــل هــو ملــك جلميــع الورثــة الذيــن يعــودون‬\n\n\n‫‪423‬‬\n\f‫لوالــدي وانــه ليــس للمدعيــة وال ملورثهــا اي عقــار بالطائــف امــا بالنســبة‬\n‫للعقــار الواقــع بالطائــف فهــو عائــد لــي مبوجــب صــك شــرعي واطلــب‬\n‫املهلــة إلحضــاره هكــذا قــرر وبعــرض ذلــك علــى املدعيــة قالــت ال اعلــم‬\n‫عــن مــا ذكــره اي شــيء وان املدعــى عليــه متهــرب ومتهــاون وان هنــاك‬\n‫دعــوى قــد انتهــت عنــد القســم القضائــي التاســع قبــل مدة هكــذا قررت‬\n‫وبعــرض اخلطــاب الــوارد مــن القســم القضائــي التاســع علــى املدعــى‬\n‫عليــه قــال كل مــا جــاء فيــه غيــر صحيــح وســوف اتابــع اخلطــاب مــرة‬\n‫اخــرى هكــذا قــرر ثــم رفعــت اجللســة ) ا‪.‬ه ـ ويف هــذه اجللســة حضــرت‬\n‫املــرأة املدعيــة ‪ ...‬املدونــة هويتهــا ســابقا وحضــر حلضورهــا املدعــى‬\n‫عليــه أخوهــا الشــقيق وقــد عــرف باملدعيــة وهــو‪ ...‬املدونــة هويتــه ســابقا‬\n‫وقــررت املدعيــة بقولهــا إن املدعــى عليــه هــذا احلاضــر قــد اســتولى‬\n‫علــى تركــة والــدى املتــويف وهــي مجموعــة مــن العقــارات التــي التعــد‬\n‫وال حتصــى وهــي عــدة بســاتني وعــدة بيــوت وصكوكهــا مــع املدعــى‬\n‫عليــه هــذا احلاضــر كمــا أن والــدي خلــف غنمــا وابــا وبقــرا وقــد باعهــا‬\n‫هــذا احلاضــر وأخــذ ثمنهــا واســتثمرها يف عــدة اســتثمارات اطلــب إلــزام‬\n‫هــذا احلاضــر بإعطائــي نصيبــي مــن تركــة والــدي كمــا اطلــب إلزامــه‬\n‫بتســليم صكــوك العقــارات التــي لديــه هكــذا ادعــت وبعــرض الدعــوى‬\n‫علــى املدعــى عليــه قــال إن والــدي تــويف قبــل اربعــن ســنة ولــم يخلــف‬\n‫إال ثالثــة ركبــان وليــس عليهــا صكــوك وأمــا مــا ذكرتــه يف بقيــة‬\n‫دعواهــا فغيــر صحيــح والركبــان ليــس فيهــا شــيء ولســت مســتوليا‬\n‫عليهــا هكــذا أجــاب فطلبــت مــن املدعيــة البينــة علــى صحــة دعواهــا‬\n‫فقالــت ال بينــة لــدي والشــاهد علــى صحــة كالمــي هــو اهلل ســبحانه‬\n‫وتعالــى كمــا انــي ال اطلــب ميــن املدعــى عليــه هــذا احلاضــر علــى نفــي‬\n\n\n                                                                                    ‫‪424‬‬\n\f      ‫دعــواي لكونــي أعلــم أن مــال والــدي لديهــم هكــذا أجابــت فســألت‬\n      ‫أطــراف الدعــوى هــل مت اســتخراج اثبــات وفــاة وحصــر ورثــة لوالدهمــا‬\n      ‫فقــال املدعــى عليــه إننــي لــم أخــرج صــك اثبــات وفــاة لوالــدي حيــث‬\n      ‫تــويف قدميــا ولــم نحتــج لذلــك هكــذا قــررت كمــا ذكــرت املدعيــة‬\n      ‫أنهــا ال تعلــم عــن ذلــك وأن والدهــا تــويف قبــل أربعــن ســنة وأن ورثتــه‬\n      ‫انحصــرت يف زوجتــه ‪ ...‬ويف أوالده ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬ال وارث لــه ســواهم‬\n      ‫هكــذا قــررت وصــادق علــى ذلــك املدعــي فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واالجابــة ومبــا أنــه ال بينــة للمدعيــة علــى دعواهــا ولــم تطلــب‬\n      ‫ميــن املدعــى عليــه علــى نفــي الدعــوى وقــد قــال النبــي صلــى اهلل عليــه‬\n      ‫وســلم (البينــة علــى املدعــي واليمــن علــى مــن انكــر) فقــد صرفــت‬\n      ‫النظــر عــن دعــوى املــرأة املدعيــة ‪ ...‬ضــد املدعــى عليــه ‪ ...‬وبــه حكمــت‬\n      ‫وأفهمــت املدعيــة بــأن لهــا ميــن املدعــى عليــه متــى أرادت ففهمــت ذلــك‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة كمــا أن املدعيــة لــم‬\n      ‫تقــرر شــيئا وأفهمــت أن لهــا ثالثــون يومــا مــن يــوم الســبت القــادم إلــم‬\n      ‫حتضــر اعتراضــا فــإن احلكــم يكــون قطعيــا ففهمــت ذلــك وعليــه‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم حــرر يف‪1434/05/27‬ه ـ الســاعة الثانيــة عشــر ظهــرا ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم الســبت‪1434/06/03‬هـ افتتحــت‬\n      ‫اجللســة يف متــام الســاعة العاشــرة وخمســة واربعــن دقيقــة وفيهــا وردت‬\n      ‫الالئحــة االعتراضيــة املقدمــة مــن املدعيــة ذو‪ ...‬املقيــدة بهــذه احملكمــة‬\n      ‫برقــم ‪ 341324102‬يف ‪1434/06/03‬ه ـ واملكونــة مــن ورقــة واحــدة‬\n      ‫وجــرى اطالعــي عليهــا فلــم أجــد بهــا مــا يؤثــر علــى مــا حكمــت بــه‬\n      ‫ولــذا فاحلكــم علــى حالــه وأمــرت برفــع كامــل أوراق املعاملــة حملكمــة‬\n\n\n‫‪425‬‬\n\f‫االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‪1434/06/03‬ه ـ الســاعة‬\n                                                       ‫احلاديــة عشــر صباحــا‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف برقــم ‪33512142‬‬\n‫وتاريــخ ‪1434/6/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ...‬القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34225205‬‬\n‫وتاريــخ ‪1434/5/28‬هـ ـ واملتضمــن دعــوى ‪ ...‬ضــد ‪ ...‬واحملكــوم فيــه‬\n‫مبــا دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه تقــرر املوافقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                        ‫وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪426‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":420,"source_page_end":426,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"06bdd641e04fae29c6a1499e13359413842d6c5dd990ddddee46f2ca524fbc2d","normalized_text_hash":"6005a1dfaa798bc8e20876a40d54763c06a6c7a0463aaee1bacdcc64fe733acd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v9-p420-34225205"},{"id":"2d2314df-83b5-5359-a68a-8a19a0369f04","document_type":"judgment","category":"judicial","subcategory":"general","title":"قسمة تركة -إقامة بعض الورثة خارج اململكة وعدم معرفة محل إقامتهم -املطالبة ببيع اإلرث باملزاد العلني وتقسيمة على الورثة حسب النصيب الشرعي -بيع اإلرث وتقسيم األنصبة على الورثة وإيداع نصيب الغائبن بيت املال .","document_number":"34324097","case_number":"34378916","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة ففي هذا اليوم اخلميس 1434/09/03ه ويف متام الساعة الثانية عشر فتحت","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/22","year":"1434","subject":"قسمة تركة -إقامة بعض الورثة خارج اململكة وعدم معرفة محل إقامتهم -املطالبة ببيع اإلرث باملزاد العلني وتقسيمة على الورثة حسب النصيب الشرعي -بيع اإلرث وتقسيم األنصبة على الورثة وإيداع نصيب الغائبن بيت املال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34324097 :‬تاريخه‪1434/9/22 :‬هـ‬\n                         ‫رقم الدعوى‪34378916 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34338485:‬تاريخه‪1434/10/22 :‬هـ‬\n\n\n      ‫قســمة تركــة ‪ -‬إقامــة بعــض الورثــة خــارج اململكــة وعــدم معرفــة محــل‬\n      ‫إقامتهــم‪ -‬املطالبــة ببيــع اإلرث باملــزاد العلنــي وتقســيمة علــى الورثــة‬\n      ‫حســب النصيــب الشــرعي‪ -‬بيــع اإلرث وتقســيم األنصبــة علــى الورثــة‬\n                                           ‫وإيــداع نصيــب الغائبــن بيــت املــال ‪.‬‬\n\n\n\n                         ‫املادة‪/27‬و‪ 6-5/‬من نظام املرافعات الشرعية والئحته‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليهمــا الغائبــن بــأن زوجهــا الســابق قــد‬\n      ‫تــويف وهــي التــزال يف عصمتــه وانحصــر ارثــه فيهــا ويف أخويه الشــقيقني‬\n      ‫املدعــى عليهمــا ومــن ضمــن تركــة مورثهــا ســيارة ذكــرت نوعهــا‬\n      ‫وتطلــب بيعهــا باملــزاد العلنــي وإعطــاء كل واحــد نصيبــه منهــا هكــذا‬\n      ‫ادعــت‪ ،‬ومبــا أن املدعيــة ال تعلــم عنــوان املدعــى عليهمــا ويقيمــان خــارج‬\n      ‫اململكــة وبنــاء علــى املــادة‪/27‬و‪ 6-5/‬مــن نظــام املرافعــات الشــرعية‬\n      ‫والئحتــه جــرى ســماع الدعــوى غيابيـاً‪ ،‬بينــة املدعيــة هــي وثيقــة ملكيــة‬\n      ‫الســيارة وصــك حصــر اإلرث‪ ،‬ملــا تقــدم صــدر احلكــم ببيــع الســيارة‬\n      ‫باملــزاد العلنــي وقســمة قيمتهــا علــى ورثــة املتوفــى لــكل واحــد منهــم‬\n      ‫نصيبــه الشــرعي وإيــداع نصيــب الغائبــن يف بيــت املــال‪ ،‬رفــع احلكــم‬\n\n‫‪427‬‬\n\f‫حملكمــة االســتئناف لتدقيقــه‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n            ‫اخلامســة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .......‬القاضــي باحملكمــة العامــة باملدينــة املنــورة ففــي هــذا اليــوم‬\n‫اخلميــس ‪1434/09/03‬ه ـ ويف متــام الســاعة الثانيــة عشــر فتحــت‬\n‫ـاء علــى املعاملــة املقيــدة يف هــذه احملكمــة برقــم‬      ‫اجللســة األولــى بنـ ً‬\n‫‪ 341958372‬يف ‪1434/08/13‬ه ـ واحملالــة إلينــا مــن قبــل فضيلــة‬\n‫الرئيــس ‪ 34378916‬يف ‪1434/08/13‬ه ـ مبوجبــه حضــرت املــرأة‪/‬‬\n‫‪.......‬مصريــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم يحمــل الهويــة‬\n‫الوطنيــة رقــم ‪.......‬جــوازات املدينــة املنــورة واملعــرف بهــا مــن قبــل زوجهــا‬\n‫املقيــم ‪ .......‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪.......‬جــوازات‬\n‫املدينــة املنــورة وادعــت علــى الغائبــن يف مجلــس احلكــم املدعــو ‪.......‬‬\n‫أوالد ‪ .......‬املقيمــن يف جمهوريــة مصــر العربيــة وال تعلــم املدعيــة محــل‬\n‫اقامــة معــروف للمدعــى عليهــم قائلــة يف حتريــر دعواهــا عليهــم إن‬\n‫املقيــم ‪.......‬مصــري اجلنســية كان هــو زوجــي الســابق وقــد تــويف بتاريــخ‬\n‫‪1433/02/07‬ه ـ وكنــت ال زلــت يف عصمتــه وقــد انحصــر ارثــه يف‬\n‫أنــا ويف أخويــه الشــقيقني املدعــى عليهمــا مبوجــب صــك حصــر اإلرث‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 34266724‬يف ‪1434/07/12‬هـ وإن‬\n‫مــن ضمــن تركــة مورثــي ‪ ....‬ســيارته نــوع مرســيدس صنــع عــام ‪1990‬م‬\n‫رقــم الهيــكل ‪ 522200‬اللــون ذهبــي رقــم اللوحــة ‪.......‬وطرازهــا ‪300‬‬\n‫أس أي لــذا أطلــب اثبــات ذلــك وبيــع الســيارة باملــزاد العلنــي واعطــاء‬\n\n                                                                                         ‫‪428‬‬\n\f      ‫كل واحــد منــا نصيبــه منهــا هــذه دعــواي ونظــر ًا ملــا نصــت عليــه املــادة‬\n      ‫الســابعة والعشــرون يف الفقــرة ه ـ يف الالئحــة السادســة واخلامســة مــن‬\n      ‫ذات املــادة لــذا فقــد قــررت ســماع الدعــوى غيابيـ ًا ثــم جــرى منــا ســؤال‬\n      ‫املدعــى عليهــا هــل لديهــا بينــة علــى دعواهــا فأجابــت قائلــة نعــم لــدي‬\n                     ‫بينــة وســوف أحضرهــا يف اجللســة القادمــة هكــذا أجابــت‬\n      ‫وعليــه أمــرت برفــع اجللســة ثــم يف يــوم االثنــن ‪1434/9/14‬ه ـ ويف متــام‬\n      ‫الســاعة احلاديــة عشــر صباحــا فتحــت اجللســة الثانيــة وفيهــا حضــرت‬\n      ‫املدعيــة ويرافقهــا زوجهــا املعــرف بهــا املدونــة هويتهمــا ســابقا ثــم جــرى‬\n      ‫منــا ســؤال املدعيــة عــن البينــة التــي وعــدت بإحضارهــا يف هــذه اجللســة‬\n      ‫فأجابــت قائلــة نعــم أحضرتهــا ثــم أبــرزت لنــا وثيقــة ملكيــة الســيارة‬\n      ‫املوصوفــة يف الدعــوى فوجدتهــا كمــا ذكــرت املدعيــة يف دعواهــا‬\n      ‫ثــم جــرى منــي االطــاع علــى صــك حصــر امليــراث املشــار إليــه بعاليــة‬\n      ‫فوجدتــه كمــا ذكــرت املدعيــة فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واالطــاع علــى أوراق املعاملــة ونظــرا ملــا تضمنــه صــك حصــر امليــراث‬\n      ‫ووثيقــة ملكيــة الســيارة املوصوفــة يف الدعــوى ومبــا أن املدعيــة ال تعلــم‬\n      ‫محــل إقامــة املدعــى عليهمــا خــارج اململكــة ونظــرا ملــا نصــت عليــه‬\n      ‫املــادة الســابعة والعشــرون يف الفقــرة ه ـ مــن نظــام املرافعــات الشــرعية‬\n      ‫يف الالئحــة اخلامســة والسادســة جلميــع مــا ذكــر فقــد حكمــت ببيــع‬\n      ‫الســيارة املوصوفــة يف الدعــوى باملــزاد العلنــي وقســمة قيمتهــا علــى ورثــة‬\n      ‫املتــويف ‪.......‬لــكل واحــد منهمــا نصيبــه املقــرر شــرعا وإيــداع نصيــب‬\n      ‫الغائبــن عــن مجلــس احلكــم يف بيــت مــال املســلمني وامــرت برفــع‬\n      ‫احلكــم حملكمــة اإلســتئناف لتدقيــق احلكــم حســب املتبــع نظامــا وبــه‬\n      ‫اختتمــت اجللســة يف متــام الســاعة احلاديــة عشــر والنصــف صباحــا وصلــى‬\n\n\n‫‪429‬‬\n\f                    ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/9/14‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ ‪ .......‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n‫املســجل بعــدد ‪.......‬وتاريــخ ‪1434/9/22‬ه ـ املتضمــن دعــوى ‪.......‬ضــد‬\n‫ورثــة ‪.......‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم‬\n‫وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم ‪ .‬وبــاهلل التوفيــق وصل ــى‬\n                           ‫اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪430‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬   ‫م‬\n\n          ‫مطالبة بإعادة وقف إلى مستحقيه بعد أن آل‬\n  ‫‪5‬‬        ‫إلى جمعية خيرية اعتقا ًدا بانقطاع الوقف‬     ‫وقف‬      ‫‪1‬‬\n\n           ‫مطالبة بجزء من نصيب أحد املستحقني‬\n  ‫‪30‬‬             ‫للوقف الذي تويف عقيما‬                 ‫وقف‬      ‫‪2‬‬\n\n          ‫إثبات وقفية مسجد ممن اشترى مزرعة وهو‬\n  ‫‪57‬‬     ‫بها‪ ،‬وإفهام املدعى عليه الرجوع على من باعه‬    ‫وقف‬      ‫‪3‬‬\n                       ‫إذا كان غره‬\n\n          ‫مدعى عليهما بالتعويض‬\n                          ‫ً‬    ‫مطالبة ناظر وقف‬\n  ‫‪69‬‬       ‫عن طردهما مستأجرين لعقار موقوف‬              ‫وقف‬      ‫‪4‬‬\n\n         ‫مطالبة مستثمر لعقار موقوف نزعت ملكيته‬\n  ‫‪78‬‬     ‫ناظري الوقف بالتعويض عن مدة العقد بحسب‬\n                                           ‫َ‬           ‫وقف‬      ‫‪5‬‬\n                       ‫ما ا ُتفق عليه‬\n\n         ‫مطالبة بعض ورثة بإلغاء وقف أبيهم لتضررهم‬\n  ‫‪84‬‬             ‫ولكونه أكثر من الثلث‬                  ‫وقف‬      ‫‪6‬‬\n\n          ‫مطالبة ولي امرأة قاصرة بإعادة ما ُأفرغ من‬\n ‫‪235‬‬          ‫صوريا‬\n               ‫ً‬      ‫عقار موليته لكونه إفراغً ا‬        ‫هبة‬     ‫‪7‬‬\n\n          ‫قصر بإثبات هبة‬\n                      ‫مطالبة ورثة متوفى بعضهم ّ‬\n ‫‪245‬‬                     ‫مورثهم‬                         ‫هبة‬     ‫‪8‬‬\n\n          ‫مطالبة بعض ورثة بإبطال هبة مورثهم بعض‬\n ‫‪252‬‬            ‫ورثته حني مرضه قبل وفاته‬                ‫هبة‬     ‫‪9‬‬\n\n         ‫مطالبة زوج ُفسخ نكاحه بإعادة هدايا الزواج‬\n ‫‪260‬‬               ‫وإيجار الشقة وقاعة الفرح‬             ‫هبة‬     ‫‪10‬‬\n\f‫الصفحة‬                    ‫املوضوع‬                      ‫التصنيف‬    ‫م‬\n\n         ‫مطالبة زوج زوجته التي لم يدخل بها بإرجاع‬\n ‫‪265‬‬              ‫املهر وأطقم ذهب وهدايا‬                 ‫هبة‬      ‫‪11‬‬\n\n          ‫مطالبة زوج بإرجاع هبة بعد انفكاك عقد‬\n ‫‪273‬‬                   ‫الزوجية‬                           ‫هبة‬      ‫‪12‬‬\n\n          ‫مطالبة زوج بإعادة هبته عقار ًا لزوجته بعد‬\n ‫‪279‬‬                ‫حدوث شقاق بينهما‬                     ‫هبة‬      ‫‪13‬‬\n\n         ‫مدع بيع عقار مو ِّرثه الذي وهبه ألحد‬\n                                          ‫مطالبة ٍ‬\n ‫‪285‬‬      ‫أبنائه لعتهه وإعاقته‪ ،‬وتسليمه نصيبه منه‬        ‫هبة‬      ‫‪14‬‬\n\n          ‫البن وارث لكون‬\n                    ‫ادعاء صورية متلك أرض ٍ‬\n ‫‪295‬‬               ‫األب غير سعودي‬                     ‫قسمة تركة‬   ‫‪15‬‬\n\n         ‫مورث له تركة داخل اململكة وخارجها‪،‬‬\n         ‫وتطالب املدعية أصالة عن نفسها ووكالة‬\n ‫‪299‬‬     ‫عن أخواتها بنصيبهن‪ ،‬واملورث قد نقل بعض‬       ‫قسمة تركة‬   ‫‪16‬‬\n           ‫األمالك إلى ابنه املدعى عليه كوصية‬\n\n         ‫مطالبة بقسمة تركة‪ ،‬وأحد الورثة يرغب‬\n ‫‪330‬‬     ‫يف شراء عقار منها‪ ،‬وآخر يدعي متلكه يف‬        ‫قسمة تركة‬   ‫‪17‬‬\n          ‫احلقيقة لعقار منها وأن مورث أوصى له به‬\n\n         ‫مطالبة ورثة مبحاسبة أحدهم املتولي تأجير‬\n ‫‪339‬‬      ‫عقاراتهم املورثة وتوضيح دخلها وتسليمهم‬      ‫قسمة تركة‬   ‫‪18‬‬\n                        ‫نصيبهم منها‬\n\n         ‫مطالبة بقسمة تركة‪ ،‬وبعض الورثة يدعي‬\n ‫‪365‬‬              ‫وصية املورث له بعقار‬                ‫قسمة تركة‬   ‫‪19‬‬\n\n          ‫مطالبة بعض الورثة للبقية بإمتام بيع عقار‬\n ‫‪374‬‬        ‫موروث مت بيعه مبوافقة جميع الورثة‬         ‫قسمة تركة‬   ‫‪20‬‬\n\f‫الصفحة‬                    ‫املوضوع‬                        ‫التصنيف‬    ‫م‬\n\n         ‫احلكم ببيع عقار موروث باملزاد العلني وقسمة‬\n          ‫ثمنه بني الورثة بحسب أنصابهم الشرعية بعد‬\n ‫‪390‬‬       ‫مطالبة املدعية بذلك‪ ،‬وتخلف أحد املدعى‬        ‫قسمة تركة‬   ‫‪21‬‬\n                             ‫عليهم‬\n\n          ‫مطالبة ببيع عقار موروث وإعطاء كل وارث‬\n ‫‪398‬‬      ‫نصيبه الشرعي‪ ،‬ويف الورثة قاصر وموصية‬          ‫قسمة تركة‬   ‫‪22‬‬\n                       ‫بثلث مالها‬\n\n           ‫مطالبة وارث ببيع عقارات مورثهم باملزاد‬\n           ‫العلني وتسليمه نصيبه منها‪ ،‬ودم إمكان‬\n ‫‪408‬‬      ‫قسمتها بني الورثة‪ ،‬وصكوكها خالية من‬           ‫قسمة تركة‬   ‫‪23‬‬\n                        ‫املساحة الكلية‬\n\n          ‫مطالبة وارثة بنصيبها مما تدعيه من أمالك‬\n ‫‪420‬‬                 ‫مورثها وال بينة لها‬                ‫قسمة تركة‬   ‫‪24‬‬\n\n           ‫مطالبة وارثة ببيع عني موروثة وقسمتها على‬\n ‫‪427‬‬     ‫الورثة‪ ،‬والورثة سوى املدعية خارج اململكة وال‬   ‫قسمة تركة‬   ‫‪25‬‬\n                      ‫يعرف محل إقامتهم‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9084d743-5338-5ad3-a401-5fb9cb568866","source_page_start":427,"source_page_end":433,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_u